   export async function loadPublishedDocument(
     folioId: string,
   ): Promise<PublishResult | null> {
     const doc = await loadMetaFromIdb<DocumentRef>(docMetaKey(folioId));
     const publication =
       await loadMetaFromIdb<PublicationRef>(PUBLICATION_META_KEY);
     if (!doc?.uri || !publication?.uri) return null;
     const documentParts = parseAtUri(doc.uri);
     const publicationParts = parseAtUri(publication.uri);
     if (
       !documentParts ||
       !publicationParts ||
       documentParts.did !== publicationParts.did
     ) {
       return null;
     }
     return {
       uri: doc.uri,
       publicationUri: publication.uri,
       viewerUrl: standardSiteDocumentUrl(
         documentParts.did,
         publicationParts.rkey,
         documentParts.rkey,
       ),
       explorerUrl: `https://pdsls.dev/${encodeURIComponent(doc.uri)}`,
     };
   }
   ```

   This restores “published” state solely from IndexedDB and never checks the PDS, despite the new flow treating the PDS as the source of truth. If a document was deleted/reassigned from another client, Twyne still renders the re-publish/unpublish state and a broken reader URL indefinitely. It also cannot confirm the cached DID belongs to the currently signed-in ATProto agent.

   Severity: 3  
   Confidence: 0.97

2. `logic_error` — `packages/twyne-tools/src/mcp.ts`

   Code:
   ```ts
   server.registerTool(
     "twyne_upsert_citations",
     {
       title: "Save Twyne citations",
       description:
         "Bulk create or update cited sources for a folio. Call this after using external sources so claims can retain their provenance; pass an existing citation ID to update it.",
       inputSchema: {
         folioId,
         entries: z.array(citationEntry).min(1).max(100),
       },
       annotations: { destructiveHint: false, idempotentHint: true },
     },
     async ({ folioId, entries }) =>
       resultOf(() => client.putCitations(folioId, entries as CitationEntry[])),
   );
   ```

   The tool declares itself idempotent although citation IDs are optional and the server generates a new UUID whenever one is absent. Retrying the same MCP call can therefore create duplicate citations; clients may retry specifically because this annotation says doing so is safe. Mark it non-idempotent or provide deterministic deduplication.

   Severity: 2  
   Confidence: 0.99

3. `logic_error` — `convex/integrations.ts`

   Code:
   ```ts
   handler: async (ctx) => {
     const userId = await requireIdentity(ctx);
