      "codePart": "/* ── CLI / MCP integration API ─────────────────────────────────────
 * The local tools use a personal bearer token created from Settings. The
 * database stores only its SHA-256 digest; after resolving that digest here,
 * every operation runs through an internal function with the verified owner.
 */",
      "severity": 5,
      "confidence": 1.0
    },
    {
      "issueCode": "test_coverage",
      "description": "The requested identity-lifecycle regression has no automated test. The added tests only verify initialization options and never exercise anonymous startup, returning-anonymous startup, anonymous-to-identified, identified-to-anonymous, or user-A-to-user-B transitions. Consequently, the exact requirement not to reset returning anonymous users can regress undetected.",
      "location": "src/utils/posthog-context.tsx",
      "codePart": "    if (auth.value.user) {
      const previousUserId = client.get_property("$user_id");
      if (previousUserId && previousUserId !== auth.value.user.id) {
        client.reset();
      }
      client.identify(auth.value.user.id, {
        email: auth.value.user.email,
        name: auth.value.user.name,
        auth_provider: auth.value.provider,
      });

      if (previousUserId !== auth.value.user.id) {
        client.capture("sign_in_completed", {
          analytics_version: 1,
          provider: auth.value.provider ?? "convex",
        });
      }
    } else if (client.get_property("$user_id")) {
      // `reset()` creates a fresh anonymous id. Only do that when an
      // identified session actually ended; resetting every anonymous page
      // load made the same returning writer look like a brand-new person.
      client.reset();
    }",
      "severity": 3,
      "confidence": 0.99
    },
    {
      "issueCode": "type_safety_violation",
      "description": "The integration boundary stores citation objects without requiring or normalizing `url`, although the existing `BibEntry` contract requires a string URL and UI code invokes `entry.url.replace(...)`. A valid CLI/MCP citation containing only a title or DOI therefore enters the bibliography as `url: undefined` and can crash the citations UI.",
      "location": "convex/integrations.ts",
      "codePart": "    for (const raw of entries) {
      if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
        throw new Error("Each citation must be an object");
      }
      const entry = { ...raw, folioId } as Record<string, unknown>;
      if (typeof entry.title !== "string" || !entry.title.trim()) {
        throw new Error("Each citation needs a title");
      }
      if (typeof entry.id !== "string" || !entry.id.trim()) {
        entry.id = crypto.randomUUID();
      }
      if (typeof entry.accessedAt !== "number") entry.accessedAt = Date.now();",
      "severity": 4,
      "confidence": 0.99
    },
    {
      "issueCode": "incorrect_algorithm",
      "description": "When remote content wins, it is saved through a helper that assigns `Date.now()` instead of preserving `fc.updatedAt`. The local snapshot consequently loses the source revision timestamp and may appear newer than a subsequent genuine remote revision, particularly with clock skew, causing that update to be skipped.",
      "location": "src/utils/convex-sync.ts",
      "codePart": "  // Folio content — per-folio, newer-wins.
  for (const fc of remote.folioContent) {
    const localEntry = local.folioContent.find((l) => l.folioId === fc.folioId);
