      "location": "convex/integrations.test.ts",
      "codePart": "const supportsViteModules = typeof import.meta.glob === "function";
const modules = supportsViteModules ? import.meta.glob("./**/*.ts") : {};
const describeConvex = supportsViteModules ? describe : describe.skip;",
      "severity": 4,
      "confidence": 1.0
    },
