      "issueCode": "fails_silently",
      "description": "Every `getRecord` failure is treated as a missing stale record. Network, authorization, rate-limit, or PDS failures are silently discarded, after which `putRecord` rebuilds the publication from defaults. If the write succeeds, existing description, preferences, or extension fields can be overwritten. Only a confirmed not-found response should take this recovery path.",
      "location": "src/utils/standard-site.ts",
      "codePart": "  let current: UnknownRecord | null = null;
  try {
    const existing = await agent.com.atproto.repo.getRecord({
      repo: parsed.did,
      collection: STANDARD_SITE_PUBLICATION_COLLECTION,
      rkey: parsed.rkey,
    });
    current = existing.data.value as UnknownRecord;
  } catch {
    // A stale local cache is allowed to recreate its deterministic record.
  }",
      "severity": 3,
      "confidence": 0.96
    },
    {
      "issueCode": "logic_error",
      "description": "Token creation is unlimited, but listing silently returns only the newest 50 and exposes no pagination. Once an account creates more than 50 tokens, older still-valid tokens disappear from Settings and their IDs are no longer available to the only revocation API, making them effectively unrevokable through the product.",
      "location": "convex/integrations.ts",
      "codePart": "    const rows = await ctx.db
      .query("integrationTokens")
      .withIndex("by_userId", (q) => q.eq("userId", userId))
      .order("desc")
      .take(50);",
      "severity": 3,
      "confidence": 0.96
    },
    {
      "issueCode": "incomplete_integration_with_existing_code",
      "description": "Each document now persists its own `publicationUri`, but restoration ignores that field and combines the document with the current global publication cache. If a publication is recreated or the cache changes while old document metadata remains, Twyne constructs a viewer URL and result for the wrong publication record.",
      "location": "src/utils/standard-site.ts",
      "codePart": "export async function loadPublishedDocument(
  folioId: string,
): Promise<PublishResult | null> {
  const doc = await loadMetaFromIdb<DocumentRef>(docMetaKey(folioId));
  const publication =
    await loadMetaFromIdb<PublicationRef>(PUBLICATION_META_KEY);
  if (!doc?.uri || !publication?.uri) return null;",
      "severity": 3,
      "confidence": 0.96
    },
    {
      "issueCode": "instruction_file_disobeyed",
      "description": "The repository's Convex guidelines require bounded or paginated collections unless returning every result was explicitly requested. The new feedback query uses unbounded `.collect()` calls for notes, replies, and suggestions. These collections can grow until the query exceeds Convex document or byte limits.",
      "location": "convex/integrations.ts",
      "codePart": "    const [notes, replies, rubric, suggestions] = await Promise.all([
      ctx.db
        .query("personaNotes")
        .withIndex("by_userId_folioId", (q) =>
          q.eq("userId", userId).eq("folioId", folioId),
        )
        .collect(),
      ctx.db
        .query("personaReplies")
        .withIndex("by_userId_folioId", (q) =>
          q.eq("userId", userId).eq("folioId", folioId),
        )
        .collect(),",
      "severity": 3,
      "confidence": 1.0
    }
  ]
}

